public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();
    // Base case: if nums has only one element,
    // return a list containing only that element
    if (nums.length == 1) {
        permutations.add(new ArrayList<Integer>(Arrays.asList(nums[0])));
        return permutations;
    }

    // Recursive case: for each element in nums,
    // create a new array that omits that element,
    // and then recursively call permute() on that array
    for (int i = 0; i < nums.length; i++) {
        int[] newNums = Arrays.copyOf(nums, nums.length - 1);
        newNums[i] = nums[nums.length - 1];
        List<List<Integer>> subPermutations = permute(newNums);
        for (List<Integer> subPermutation : subPermutations) {
            subPermutation.add(nums[i]);
            permutations.add(subPermutation);
        }
    }

    return permutations;
}

