public int findLargestSubstring(List<String> strings) {
    // Initialize a variable to store the length of the largest string found
    int maxLength = -1;

    // Loop through each string in the list
    for (String str : strings) {
        // Find the length of the current string
        int length = str.length();

        // Check if the current string is longer than the previously found longest string
        if (length > maxLength) {
            maxLength = length;
        }

        // Check if the current string is a substring of any of the other strings in the list
        for (String otherStr : strings) {
            if (otherStr.contains(str)) {
                // If the current string is a substring of another string,
                // we know that the other string must be longer than the current string
                // because the current string is a substring of it.
                // Therefore, we can update the length of the longest string accordingly.
                maxLength = Math.max(maxLength, otherStr.length());
            }
        }
    }

    // Return the length of the largest string found
    return maxLength;
}

