public double trimMean(int[] arr) {
    int n = arr.length;
    int m = n / 20;
    int upperM = n - m;

    int min = arr[0];
    int max = arr[n - 1];

    for (int i = 1; i < m; i++) {
        min = Math.min(min, arr[i]);
        max = Math.max(max, arr[n - i - 1]);
    }

    double mean = 0;
    int count = 0;

    for (int i = m; i < upperM; i++) {
        if (arr[i] < min || arr[i] > max) {
            continue;
        }
        mean += arr[i];
        count++;
    }

    return mean / count;
}

