public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 1 || edges.length == 0) {
        return 0;
    }

    int[] parents = new int[n];
    for (int i = 1; i < n; i++) {
        parents[i] = i;
    }

    for (int i = 0; i < edges.length - 1; i++) {
        union(edges[i][0], edges[i][1], parents);
    }

    int minTime = 0;
    for (int i = 0; i < hasApple.length; i++) {
        if (hasApple[i]) {
            int parent = find(i, parents);
            minTime = Math.max(minTime, Math.abs(parent - i));
        }
    }

    return minTime;
}

