public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    double average = (double) sum / nums.length;
    for (int i = 0; i < nums.length; i++) {
        int leftSum = 0;
        for (int j = 0; j < i; j++) {
            leftSum += nums[j];
        }
        int rightSum = sum - leftSum;
        if (leftSum == rightSum) {
            return true;
        }
    }
    return false;
}

