public int minCostClimbingStairs(int[] cost) {
  int minCost = 0;
  int currentStep = 0;
  while (currentStep < cost.length) {
    // Check if we can climb two steps from the current step
    if (currentStep + 1 < cost.length && cost[currentStep] + cost[currentStep + 1] < cost[currentStep + 2]) {
      minCost += cost[currentStep] + cost[currentStep + 1];
      currentStep += 2;
    } else {
      minCost += cost[currentStep];
      currentStep++;
    }
  }
  return minCost;
}

