public static boolean hasAllCodes(String s, int k) {
        BitSet bitSet = new BitSet();
        for (int i = 0; i <= s.length() - k; i++) {
            bitSet.set(Integer.parseInt(s.substring(i, i + k), 2));
        }
        return bitSet.size() == Math.pow(2, k);
    }

