public static int minInsertions(String s) {
        Stack<Character> stack = new Stack<>();
        for (char c : s.toCharArray()) {
            if (c == '(') {
                stack.push(c);
            } else if (c == ')') {
                if (!stack.isEmpty()) {
                    stack.pop();
                } else {
                    stack.push(c);
                }
            }
        }
        int count = 0;
        while (!stack.isEmpty()) {
            count++;
            stack.pop();
        }
        return count;
    }

