public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOps = n;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i] != arr[j]) {
                minOps++;
                int diff = arr[j] - arr[i];
                arr[i] += diff;
                arr[j] -= diff;
            }
        }
    }
    return minOps;
}

