public int minOperations(int n) {
    int minOperations = 0;
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    // Calculate the difference between the largest and smallest elements
    int max = arr[0];
    int min = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
        if (arr[i] < min) {
            min = arr[i];
        }
    }
    int diff = max - min;

    // Divide the difference by 2 and round up to the nearest integer
    int numOperations = (diff + 1) / 2;

    // Perform the appropriate number of operations
    for (int i = 0; i < numOperations; i++) {
        minOperations += 1;
        for (int j = 0; j < n; j++) {
            if (arr[j] == min) {
                arr[j] += 1;
            } else {
                arr[j] = min;
            }
        }
    }

    return minOperations;
}

