public int findMinFibonacciNumbers(int k) {
    int[] fibonacci = new int[k];
    fibonacci[0] = 1;
    fibonacci[1] = 1;
    for (int i = 2; i < k; i++) {
        fibonacci[i] = fibonacci[i - 2] + fibonacci[i - 1];
    }
    int count = 1;
    for (int i = k - 1; i >= 0; i--) {
        if (fibonacci[i] == 1) {
            count++;
        }
    }
    return count;
}

