public int minOperations(String[] logs) {
    // Create a stack to keep track of the current folder level
    Stack<String> folders = new Stack<>();
    int minOperations = 0;

    // Iterate through the logs and perform the folder operations
    for (String log : logs) {
        if (log.equals("../")) {
            // If the log is "../", pop the top folder from the stack
            if (!folders.isEmpty()) {
                folders.pop();
            }
        } else if (log.equals("./")) {
            // If the log is "./", push the current folder onto the stack
            folders.push(folders.peek());
        }
    }

    // Calculate the minimum number of steps required to return to the main folder
    while (!folders.isEmpty()) {
        if (folders.peek().equals("../")) {
            minOperations++;
        }
        folders.pop();
    }

    return minOperations;
}

