public static int minPerfectSquareSum(int n) {
    int minSquares = Integer.MAX_VALUE;
    for (int i = 1; i <= Math.sqrt(n); i++) {
        int perfectSquare = i * i;
        if (perfectSquare > n) {
            break;
        }
        int remaining = n - perfectSquare;
        int numSquares = 1 + minPerfectSquareSum(remaining);
        minSquares = Math.min(minSquares, numSquares);
    }
    return minSquares;
}

